    <div class="plantations-workspace"><section class="proposal-admin-list"><h3><?= $isDonationTab ? 'Liste des dons' : 'Liste des propositions' ?></h3><?php if ($displayFeatures === []): ?><p><?= $isDonationTab ? 'Aucun don.' : 'Aucune plantation.' ?></p><?php endif; ?><?php foreach ($displayFeatures as $feature): $properties = $feature['properties'] ?? []; $coordinates = $feature['geometry']['coordinates'] ?? [null, null]; $id = (string) ($properties['id'] ?? ''); ?>
      <?php if ($isAdministrator): ?><form class="proposal-admin-card" data-proposal-id="<?= htmlspecialchars($id) ?>" method="post" action="<?= htmlspecialchars($url($isDonationTab ? '/admin/dons/modifier' : '/admin/propositions/modifier'), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="id" value="<?= htmlspecialchars($id) ?>">
        <label>Essence<select name="species"><?php foreach ($planting['allowed_species'] as $species): ?><option value="<?= htmlspecialchars($species) ?>" <?= ($properties['species'] ?? '') === $species ? 'selected' : '' ?>><?= htmlspecialchars($species) ?></option><?php endforeach; ?></select></label>
        <?php if ($isDonationTab): ?><fieldset><legend>Conditionnement</legend><div class="objective-grid admin-objectives"><?php foreach ($planting['tree_conditioning'] as $key => $conditioning): ?><label class="objective"><input type="radio" name="conditioning" value="<?= htmlspecialchars($key) ?>" <?= ($properties['conditioning'] ?? '') === $key ? 'checked' : '' ?> required><span class="objective-tile"><span class="objective-icon"><?= htmlspecialchars($conditioning['icon']) ?></span><span><?= htmlspecialchars($conditioning['label']) ?></span></span></label><?php endforeach; ?></div></fieldset><fieldset><legend>Taille de l’arbre</legend><div class="objective-grid admin-objectives"><?php foreach ($planting['tree_sizes'] as $key => $size): ?><label class="objective"><input type="radio" name="tree_size" value="<?= htmlspecialchars($key) ?>" <?= ($properties['tree_size'] ?? '') === $key ? 'checked' : '' ?> required><span class="objective-tile"><span class="objective-icon"><?= htmlspecialchars($size['icon']) ?></span><span><?= htmlspecialchars($size['label']) ?></span></span></label><?php endforeach; ?></div></fieldset><?php else: ?><fieldset><legend>Objectifs <small>3 maximum</small></legend><div class="objective-grid admin-objectives"><?php foreach ($planting['objectives'] as $key => $objective): ?><label class="objective"><input type="checkbox" name="objectives[]" value="<?= htmlspecialchars($key) ?>" <?= in_array($key, $properties['objectives'] ?? [], true) ? 'checked' : '' ?>><span class="objective-tile"><span class="objective-icon"><?= htmlspecialchars($objective['icon']) ?></span><span><?= htmlspecialchars($objective['label']) ?></span></span></label><?php endforeach; ?></div></fieldset><?php endif; ?>
        <label>Statut<select name="status"><?php $shownStatuses = []; foreach ($statuses as $value => $label): if (isset($shownStatuses[$label])) { continue; } $shownStatuses[$label] = true; ?><option value="<?= htmlspecialchars($value) ?>" <?= ($properties['status'] ?? 'a_valider') === $value ? 'selected' : '' ?>><?= htmlspecialchars($label) ?></option><?php endforeach; ?></select></label><div class="coordinate-fields"><label>Longitude<input type="number" name="longitude" step="any" value="<?= htmlspecialchars((string) $coordinates[0]) ?>" required></label><label>Latitude<input type="number" name="latitude" step="any" value="<?= htmlspecialchars((string) $coordinates[1]) ?>" required></label></div><button>Enregistrer</button>
      </form><?php else: ?><article class="proposal-admin-card" data-proposal-id="<?= htmlspecialchars($id) ?>"><h3><?= htmlspecialchars((string) ($properties['species'] ?? ($isDonationTab ? 'Arbre' : 'Plantation'))) ?></h3><p><?= htmlspecialchars($isDonationTab ? implode(' · ', array_filter([$planting['tree_conditioning'][$properties['conditioning'] ?? '']['label'] ?? '', $planting['tree_sizes'][$properties['tree_size'] ?? '']['label'] ?? ''])) : implode(', ', $properties['objectives'] ?? [])) ?></p><p><?= htmlspecialchars($statuses[$properties['status'] ?? 'a_valider'] ?? 'Proposée') ?></p></article><?php endif; ?>
    <?php endforeach; ?></section><aside class="plantations-map-panel"><h3>Carte<?= $isDonationTab ? ' des dons' : '' ?></h3><p><?= $isAdministrator ? 'Faites glisser un repère pour modifier ses coordonnées.' : 'Vos propositions géolocalisées.' ?></p><div id="plantations-map" class="account-map"></div><section id="proposal-details" class="proposal-details" hidden><h4>Détail <?= $isDonationTab ? 'du don' : 'de la proposition' ?></h4><p id="proposal-comment"></p><div id="proposal-photos" class="proposal-photo-gallery"></div><?php if ($isAdministrator): ?><section id="proposal-contributor" class="proposal-contributor" hidden><h5>Contributeur</h5><p id="proposal-contributor-details"></p></section><?php endif; ?></section></aside></div>
