    <table class="users-table"><thead><tr><th>Nom</th><th>E-mail</th><th>Rôle</th><th>Action</th></tr></thead><tbody><?php foreach ($users as $listedUser): ?><tr class="user-row" tabindex="0" data-user-id="<?= htmlspecialchars($listedUser['id']) ?>" data-first-name="<?= htmlspecialchars($listedUser['first_name']) ?>" data-last-name="<?= htmlspecialchars($listedUser['last_name']) ?>" data-email="<?= htmlspecialchars($listedUser['email']) ?>" data-address="<?= htmlspecialchars($listedUser['address'] ?? '') ?>" data-phone="<?= htmlspecialchars($listedUser['phone'] ?? '') ?>" data-role="<?= htmlspecialchars($listedUser['role']) ?>"><td><?= htmlspecialchars($listedUser['first_name'] . ' ' . $listedUser['last_name']) ?></td><td><?= htmlspecialchars($listedUser['email']) ?></td><td><?= htmlspecialchars(str_replace('_', ' ', $listedUser['role'])) ?></td><td><?php if ($listedUser['role'] === 'super_administrateur'): ?>Protégé<?php elseif ($user['role'] === 'administrateur' && $listedUser['role'] === 'contributeur'): ?><form method="post" action="<?= htmlspecialchars($url('/admin/utilisateurs/role'), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="user_id" value="<?= htmlspecialchars($listedUser['id']) ?>"><input type="hidden" name="role" value="administrateur"><button>Passer administrateur</button></form><?php elseif ($user['role'] === 'super_administrateur' && $listedUser['role'] === 'administrateur'): ?><div class="inline-actions"><form method="post" action="<?= htmlspecialchars($url('/admin/utilisateurs/role'), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="user_id" value="<?= htmlspecialchars($listedUser['id']) ?>"><input type="hidden" name="role" value="contributeur"><button>Rétrograder</button></form><form method="post" action="<?= htmlspecialchars($url('/admin/utilisateurs/role'), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="user_id" value="<?= htmlspecialchars($listedUser['id']) ?>"><input type="hidden" name="role" value="super_administrateur"><button>Passer super-admin</button></form></div><?php endif; ?></td></tr><?php endforeach; ?></tbody></table>
  <?php endif; ?>
</main><?php require __DIR__ . '/../partials/footer.php'; ?>
<?php if ($tab === 'plantations' || $tab === 'dons'): ?><dialog id="photo-dialog" class="photo-dialog"><button type="button" class="dialog-close" aria-label="Fermer">×</button><img id="photo-dialog-image" alt="Photo de la proposition"></dialog><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const basePath=<?= json_encode($basePath) ?>;const proposalFeatures=<?= json_encode($displayFeatures, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;const canEdit=<?= $isAdministrator ? 'true' : 'false' ?>,isDonationTab=<?= $isDonationTab ? 'true' : 'false' ?>;const map=L.map('plantations-map').setView([47.531,-0.102],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);const cards=[...document.querySelectorAll('[data-proposal-id]')],details=document.querySelector('#proposal-details'),comment=document.querySelector('#proposal-comment'),gallery=document.querySelector('#proposal-photos'),photoDialog=document.querySelector('#photo-dialog'),dialogImage=document.querySelector('#photo-dialog-image');const imageUrl=path=>`${basePath}/${String(path).replace(/^\/+/, '')}`,dateFormat=new Intl.DateTimeFormat('fr-FR',{dateStyle:'long',timeStyle:'short'}),markerDetails=status=>{const cross=isDonationTab,symbol=cross?'+':'●',crossClass=cross?' proposal-marker--cross':'';if(['refusee','rejetee'].includes(status))return{className:`proposal-marker--rejected${crossClass}`,icon:symbol};if(status==='validee')return{className:`proposal-marker--validated${crossClass}`,icon:symbol};if(['arbre_plante','realisee'].includes(status))return{className:`proposal-marker--planted${crossClass}`,icon:cross?'+':'🌳'};return{className:cross?'proposal-marker--cross':'',icon:symbol};},proposalIcon=status=>{const details=markerDetails(status);return L.divIcon({className:'',html:`<span class="proposal-marker ${details.className}" aria-hidden="true">${details.icon}</span>`,iconSize:[42,42],iconAnchor:[21,21]});};const showDetails=feature=>{const properties=feature.properties||{};details.hidden=false;comment.textContent=properties.comment||'Aucun commentaire.';gallery.replaceChildren();const photos=Array.isArray(properties.photos)?properties.photos:[];if(!photos.length){const empty=document.createElement('p');empty.textContent='Aucune photo.';gallery.append(empty);return;}photos.forEach((path,index)=>{const button=document.createElement('button'),image=document.createElement('img');button.type='button';button.className='proposal-photo-thumbnail';image.src=imageUrl(path);image.alt=`Photo ${index+1} de la proposition`;button.append(image);button.addEventListener('click',()=>{dialogImage.src=imageUrl(path);photoDialog.showModal();});gallery.append(button);});};const selectProposal=(id,feature)=>{cards.forEach(card=>{card.hidden=card.dataset.proposalId!==id;});const card=document.querySelector(`[data-proposal-id="${id}"]`);if(card){card.scrollIntoView({behavior:'smooth',block:'center'});}showDetails(feature);};document.querySelector('.dialog-close').addEventListener('click',()=>photoDialog.close());photoDialog.addEventListener('click',event=>{if(event.target===photoDialog)photoDialog.close();});if(proposalFeatures.length>1)cards.forEach(card=>{card.hidden=true;});const markers=[];proposalFeatures.forEach(feature=>{const [lng,lat]=feature.geometry.coordinates,properties=feature.properties||{},createdAt=properties.created_at?dateFormat.format(new Date(properties.created_at)):'';const marker=L.marker([lat,lng],{draggable:canEdit,icon:proposalIcon(properties.status)}).addTo(map);marker.bindPopup(`<strong>${properties.species||(isDonationTab?'Arbre':'Plantation')}</strong>${createdAt?`<br><small>${createdAt}</small>`:''}`);marker.on('click',()=>selectProposal(properties.id,feature));markers.push(marker);if(canEdit){marker.on('dragend',()=>{const position=marker.getLatLng();const form=document.querySelector(`[data-proposal-id="${properties.id}"]`);if(form){form.querySelector('[name="longitude"]').value=position.lng.toFixed(6);form.querySelector('[name="latitude"]').value=position.lat.toFixed(6);selectProposal(properties.id,feature);}});}});if(markers.length){map.fitBounds(L.featureGroup(markers).getBounds(),{padding:[24,24]});}document.querySelectorAll('.admin-objectives').forEach(grid=>grid.addEventListener('change',event=>{if(grid.querySelectorAll('input:checked').length>3){event.target.checked=false;window.alert('Trois objectifs maximum.');}}));</script><?php endif; ?>
<?php if (($tab === 'plantations' || $tab === 'dons') && $isAdministrator): ?><script>const contributorPanel=document.querySelector('#proposal-contributor'),contributorDetails=document.querySelector('#proposal-contributor-details'),showContributor=feature=>{const contributor=feature.properties?.contributor||{},items=[contributor.name,contributor.email,contributor.address,contributor.phone].filter(Boolean);contributorPanel.hidden=items.length===0;contributorDetails.replaceChildren();const append=(value,href='')=>{if(!value)return;if(contributorDetails.childNodes.length)contributorDetails.append(' · ');const item=href?document.createElement('a'):document.createElement('span');item.textContent=value;if(href)item.href=href;contributorDetails.append(item);};append(contributor.name);append(contributor.email,`mailto:${contributor.email}`);append(contributor.address);append(contributor.phone,`tel:${String(contributor.phone).replace(/[^+\d]/g,'')}`);};markers.forEach((marker,index)=>marker.on('click',()=>showContributor(proposalFeatures[index])));</script><?php endif; ?>
<?php if ($tab === 'utilisateurs'): ?><script>const userForm=document.querySelector('#user-form'),userTitle=document.querySelector('#user-form-title'),userHelp=document.querySelector('#user-form-help'),userSubmit=document.querySelector('#user-form-submit'),userId=document.querySelector('#edited-user-id'),userFirstName=document.querySelector('#edited-first-name'),userLastName=document.querySelector('#edited-last-name'),userEmail=document.querySelector('#edited-email');const resetUserForm=()=>{userForm.reset();userForm.action=<?= json_encode($url('/admin/utilisateurs/creer')) ?>;userId.value='';userTitle.textContent='Créer un utilisateur';userHelp.hidden=false;userSubmit.textContent='Créer et envoyer l’invitation';document.querySelectorAll('.user-row').forEach(row=>row.classList.remove('selected'));};const editUser=row=>{userId.value=row.dataset.userId;userFirstName.value=row.dataset.firstName;userLastName.value=row.dataset.lastName;userEmail.value=row.dataset.email;userForm.action=<?= json_encode($url('/admin/utilisateurs/modifier')) ?>;userTitle.textContent='Modifier un utilisateur';userHelp.hidden=true;userSubmit.textContent='Mettre à jour le profil';document.querySelectorAll('.user-row').forEach(item=>item.classList.toggle('selected',item===row));const role=row.dataset.role,checkbox=document.querySelector('#role-administrator');if(checkbox){checkbox.checked=role==='administrateur';}else{const option=document.querySelector(`[name="role"][value="${role}"]`);if(option)option.checked=true;}};document.querySelector('#user-form-reset').addEventListener('click',resetUserForm);document.querySelectorAll('.user-row').forEach(row=>{row.addEventListener('click',event=>{if(event.target.closest('form,button,a'))return;editUser(row);});row.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();editUser(row);}});});</script><?php endif; ?>
<?php if ($tab === 'utilisateurs'): ?><script>const userAddress=document.querySelector('#edited-address'),userPhone=document.querySelector('#edited-phone'),fillUserContact=row=>{userAddress.value=row.dataset.address||'';userPhone.value=row.dataset.phone||'';};document.querySelectorAll('.user-row').forEach(row=>{row.addEventListener('click',event=>{if(!event.target.closest('form,button,a'))fillUserContact(row);});row.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' ')fillUserContact(row);});});</script><?php endif; ?>
<?php if ($tab === 'utilisateurs'): ?><script>const protectedUserRow=event=>event.target.closest('.user-row[data-role="super_administrateur"]');document.addEventListener('click',event=>{if(protectedUserRow(event)){event.preventDefault();event.stopImmediatePropagation();}},true);document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&protectedUserRow(event)){event.preventDefault();event.stopImmediatePropagation();}},true);</script><?php endif; ?>
</body></html>
